import{_ as t,o as a,c as o,ao as i}from"./chunks/framework.CVnxSqzg.js";const w=JSON.parse('{"title":"Drawing and selecting for the agent","description":"","frontmatter":{},"headers":[],"relativePath":"guide/drawing.md","filePath":"guide/drawing.md","lastUpdated":null}'),n={name:"guide/drawing.md"};function s(r,e,h,d,l,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="Drawing-and-selecting-for-the-agent" tabindex="-1">Drawing and selecting for the agent <a class="header-anchor" href="#Drawing-and-selecting-for-the-agent" aria-label="Permalink to &quot;Drawing and selecting for the agent {#Drawing-and-selecting-for-the-agent}&quot;">​</a></h1><p>A session&#39;s agent can be given what you mark in the preview pane: a drawing over an image, a drawing on a blank canvas, or text you select. It goes to the selected session, the one the agent pane shows, with your next prompt, so you can circle a peak in a figure and ask what it is, or select a paragraph and ask for a shorter one. This page calls a drawing or a selection <em>shared</em> while the agent is given it.</p><p>This works in Claude Code sessions only; see <a href="/ship-of-tools/stable/guide/drawing#What-is-not-built">What is not built</a>.</p><h2 id="Before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#Before-you-start" aria-label="Permalink to &quot;Before you start {#Before-you-start}&quot;">​</a></h2><ul><li><p><strong>Keys.</strong> Keys are written as on Linux and Windows; on a Mac, press Cmd where this page says Ctrl. A letter in a key is always lowercase: <code>Shift+d</code> is Shift and d.</p></li><li><p><strong>Which pane has the keys.</strong> The window&#39;s three columns are the navigation tree, the preview pane and the agent pane, and one pane at a time has the keys: its title bar shows its name and its keys. <code>Ctrl+ArrowRight</code> gives the keys to the pane on the right and <code>Ctrl+ArrowLeft</code> to the pane on the left, so from the navigation tree one <code>Ctrl+ArrowRight</code> reaches the preview and a second reaches the agent pane. A mouse press on text in the preview gives it the keys too.</p></li><li><p><strong>The drawing keys belong to the preview.</strong> <code>d</code>, <code>u</code>, <code>Delete</code> and <code>Shift+d</code> do what this page says only while the preview has the keys. In the navigation tree <code>d</code> downloads the selected file, <code>u</code> uploads files, and <code>Shift+d</code> pressed twice on a session in Sessions mode ends that session. Look at the preview&#39;s title bar before you press them.</p></li><li><p><strong>Words in the window&#39;s messages.</strong> The messages quoted on this page say <code>row</code> for a session, and <code>daemon</code> and <code>host</code> for Ship of Tools&#39; service (<code>sotd</code>, the background program that runs the sessions) and the computer it runs on.</p></li></ul><h2 id="Drawing-on-an-image" tabindex="-1">Drawing on an image <a class="header-anchor" href="#Drawing-on-an-image" aria-label="Permalink to &quot;Drawing on an image {#Drawing-on-an-image}&quot;">​</a></h2><ol><li><p>With the navigation tree holding the keys (<code>Ctrl+ArrowLeft</code> brings them back from another pane), press <code>f</code> for Files mode and move to an image file with the arrow keys: PNG, JPEG, GIF, BMP, WebP or TIFF. The preview shows it.</p></li><li><p>Press <code>Ctrl+ArrowRight</code> to give the preview the keys, then <code>d</code>. A box at the foot of the preview says <code>drawing on: press and drag on the image; u undo, Delete clear, d off</code>.</p></li><li><p>Hold the left mouse button and drag over the image. A red line follows the pointer.</p></li><li><p>Release the button. The box says <code>drawing shared: the agent sees it at its next prompt</code>.</p></li><li><p>Press <code>Ctrl+ArrowRight</code> again to give the agent pane the keys, type your question and send it. Claude Code shows a line such as <code>UserPromptSubmit says: Drawing: plots/peaks.png (1 stroke)</code>, and the agent is told where to read the image with your drawing on it; <a href="/ship-of-tools/stable/guide/drawing#What-the-agent-receives">What the agent receives</a> has the details.</p></li></ol><p>With the preview holding the keys:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key or button</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;"><code>d</code></td><td style="text-align:right;">Turn drawing on or off over the shown image. Turning it off leaves the ink on the image, and shared.</td></tr><tr><td style="text-align:right;">Left button, held</td><td style="text-align:right;">While drawing is on: draw a stroke. Each stroke is shared when you release it.</td></tr><tr><td style="text-align:right;">Right button, held</td><td style="text-align:right;">While drawing is on: erase each stroke the pointer crosses.</td></tr><tr><td style="text-align:right;"><code>u</code>, <code>Ctrl+z</code></td><td style="text-align:right;">While drawing is on: undo the last stroke or the last erase; right after <code>Delete</code>, bring the cleared drawing back.</td></tr><tr><td style="text-align:right;"><code>Delete</code></td><td style="text-align:right;">While drawing is on: clear the drawing.</td></tr><tr><td style="text-align:right;"><code>=</code>, <code>-</code>, arrow keys</td><td style="text-align:right;">Zoom in, zoom out and pan, as without a drawing. The ink stays where you drew it on the image.</td></tr><tr><td style="text-align:right;"><code>Shift+d</code></td><td style="text-align:right;">Show or hide <a href="/ship-of-tools/stable/guide/drawing#The-canvas">the canvas</a>.</td></tr></tbody></table><p>Nothing on screen marks that drawing is on once the box has faded. To check, drag on the image: a red line appears only while drawing is on, and <code>u</code> removes it.</p><h2 id="The-canvas" tabindex="-1">The canvas <a class="header-anchor" href="#The-canvas" aria-label="Permalink to &quot;The canvas {#The-canvas}&quot;">​</a></h2><p>With the preview holding the keys, <code>Shift+d</code> covers the preview with a blank white page, whatever file it showed. The box says <code>canvas: draw with the pointer; u undo, Delete clear, Shift+d back</code>. Drawing is always on there, and the two mouse buttons, <code>u</code>, <code>Ctrl+z</code> and <code>Delete</code> work as in the table above.</p><p><code>Shift+d</code> again shows the preview as it was, and so does moving to another file. While the canvas is hidden its drawing is kept but not shared; showing the canvas again shares it again.</p><h2 id="One-drawing-for-each-session" tabindex="-1">One drawing for each session <a class="header-anchor" href="#One-drawing-for-each-session" aria-label="Permalink to &quot;One drawing for each session {#One-drawing-for-each-session}&quot;">​</a></h2><p>A session has one drawing, on one image or on the canvas. The first stroke anywhere else replaces it, a hidden canvas&#39;s drawing included, and the window says <code>the drawing on &lt;name&gt; was replaced</code>.</p><p>Each session keeps its own drawing, and whether drawing is on, while you work in another session. Closing the window loses every session&#39;s drawing, and no agent is given one after that.</p><h2 id="Selecting-text" tabindex="-1">Selecting text <a class="header-anchor" href="#Selecting-text" aria-label="Permalink to &quot;Selecting text {#Selecting-text}&quot;">​</a></h2><ol><li><p>Show a text file of the project in the preview: markdown, source code or plain text.</p></li><li><p>Drag over the text with the left mouse button, and release. The status line, the line starting <code>status:</code> at the top of the navigation tree, says <code>selection shared: the agent sees it at its next prompt</code>.</p></li><li><p>The drag gave the preview the keys, so one <code>Ctrl+ArrowRight</code> gives them to the agent pane. Type your prompt and send it.</p></li></ol><p>Nothing is sent while you drag. The highlight is the one <code>Ctrl+c</code> copies; in a rendered markdown preview the agent is given more than the highlighted words, as described below.</p><p>Only text of a file in the project, selected in the preview, is shared. A selection in the agent pane, in a <a href="./concept-layer">concept annotation</a> or in a rendered table is not, and nothing can be selected in an image.</p><p>In a rendered markdown preview the agent is given lines of the markdown file itself, not the rendered words:</p><ul><li><p>every paragraph or heading the selection touches, whole (in a list, the paragraph of each item it touches);</p></li><li><p>in a code block, the lines the selection touches;</p></li><li><p>any table, equation or figure that lies between the parts it touches;</p></li><li><p>link definitions (<code>[name]: url</code> lines) that stand just above a paragraph it touches.</p></li></ul><p>A selection that touches nothing but a table, an equation, a figure or a horizontal rule is not shared.</p><p>The window says <code>selection not shared: this view is not the file&#39;s text</code> when the file changed after the preview read it, and when the file, before the end of the selection, breaks a line in an unusual way: with a carriage return alone or with one of Unicode&#39;s line separators.</p><h2 id="What-the-agent-receives" tabindex="-1">What the agent receives <a class="header-anchor" href="#What-the-agent-receives" aria-label="Permalink to &quot;What the agent receives {#What-the-agent-receives}&quot;">​</a></h2><p>When you release a selection or a stroke, the window tells Ship of Tools&#39; service on the computer that runs the session. At your next prompt Claude Code shows one line in the agent pane: its own words <code>UserPromptSubmit says:</code>, then a label of what was shared. The agent is given more than the label:</p><table tabindex="0"><thead><tr><th style="text-align:right;">You shared</th><th style="text-align:right;">The label</th><th style="text-align:right;">The agent is given</th></tr></thead><tbody><tr><td style="text-align:right;">A selection</td><td style="text-align:right;"><code>Selection: &lt;file&gt; lines &lt;a&gt;-&lt;b&gt;</code></td><td style="text-align:right;">The text of those lines that you selected (in a markdown preview, the lines listed under <a href="/ship-of-tools/stable/guide/drawing#Selecting-text">Selecting text</a>), which the service reads from the file itself, labeled as your selection with the file and its line numbers.</td></tr><tr><td style="text-align:right;">A drawing on an image</td><td style="text-align:right;"><code>Drawing: &lt;file&gt; (&lt;n&gt; strokes)</code></td><td style="text-align:right;">The image&#39;s path and the path of a picture of the image with your ink on it, with the request to read the picture to see what you marked.</td></tr><tr><td style="text-align:right;">A drawing on the canvas</td><td style="text-align:right;"><code>Drawing: sketch (&lt;n&gt; strokes)</code></td><td style="text-align:right;">The path of a picture of the canvas, with the request to read it.</td></tr></tbody></table><p>Every later prompt carries it again for as long as it is shared.</p><ul><li><p><strong>A long selection.</strong> The agent is given the first 2000 characters of what is shared and is told how long the whole was. In a markdown preview whole paragraphs are shared, so in a long paragraph the cut can fall before the words you selected.</p></li><li><p><strong>The picture.</strong> The service writes it under <code>.sot/captures/</code> in the project&#39;s folder, as one file per session named <code>ink-</code> and the session&#39;s internal id, and writes it again at each change to the drawing. The agent is told the path, so you never need the id. The picture is a PNG copy of the image with the ink on it, scaled down to 2000 pixels on its longer side when the image is larger. The image file itself is never changed. The picture stays in the folder after the drawing stops being shared, until the session&#39;s next drawing writes over it; add <code>.sot/captures/</code> to the project&#39;s <code>.gitignore</code> if git should not see it.</p></li><li><p><strong>One thing at a time.</strong> The agent is given a selection or a drawing, never both: the newest replaces the other. When two windows show one session, the newest from either window is the one shared, and when either window stops sharing it, it is no longer shared from the other.</p></li></ul><h2 id="What-stops-the-sharing" tabindex="-1">What stops the sharing <a class="header-anchor" href="#What-stops-the-sharing" aria-label="Permalink to &quot;What stops the sharing {#What-stops-the-sharing}&quot;">​</a></h2><p>A drawing or a selection is shared while it is on screen in the selected session&#39;s preview: the ink on the shown image or canvas, the highlight on the selected text. When it leaves the screen the agent is no longer given it, and the window shows no message for that. To be sure of what the agent has, look at the preview before you send a prompt.</p><ul><li><p><strong>To stop sharing a selection:</strong> click in the preview, or press <code>Escape</code> with the preview holding the keys. That <code>Escape</code> also does what <code>Escape</code> does there otherwise: it restores a maximized pane or the wide preview when one is on, and if neither is, gives the keys back to the navigation tree.</p></li><li><p><strong>To stop sharing a drawing:</strong> clear it with <code>Delete</code>, or erase or undo until no ink is left.</p></li></ul><p>These remove the highlight of a selection, and so stop sharing it; select again afterwards:</p><ul><li><p>showing another file, or switching to another session;</p></li><li><p>opening the editor (<code>e</code>);</p></li><li><p>a change to the file, which refreshes its preview, or to the text size;</p></li><li><p>in a markdown preview, an equation, a figure or a code block&#39;s colors appearing, each of which lays the document out again. They appear a moment after the file is shown, so select once the document has settled.</p></li></ul><p>These hide a drawing, and so stop sharing it until its image or the canvas is shown again in that session, when it is shared again by itself:</p><ul><li><p>showing another file, or the canvas over the image;</p></li><li><p>opening the editor (<code>e</code>);</p></li><li><p>switching to another session.</p></li></ul><p>A selection under the canvas is kept, and is shared again when the canvas is hidden.</p><p>Two more things stop the sharing whatever is on screen. When the window loses its connection to the computer that runs the session, nothing is shared until the connection is back, and then the window shares again what it shows. And when the window says a new selection or drawing was not shared, the one shared before it is no longer shared either.</p><p>What the agent was already given stays in that conversation&#39;s history: asked later, it can still say what it was given. A new conversation forgets it.</p><h2 id="When-the-window-says-held" tabindex="-1">When the window says <code>held</code> <a class="header-anchor" href="#When-the-window-says-held" aria-label="Permalink to &quot;When the window says `held` {#When-the-window-says-held}&quot;">​</a></h2><p><code>selection held: this row&#39;s agent started before it could take one; restart the row to share</code>, and the same words for a drawing, mean the session&#39;s agent was started without the part of Ship of Tools that hands it a selection or a drawing. Every session started on 0.7.0 is one, and stays one after the computer is updated to 0.7.1.</p><p>End the session (<code>Shift+d</code> twice on it in Sessions mode) and start a new one in the same folder, then select or draw again; <code>/resume</code> in the new session brings the earlier conversation back. If a session started on 0.7.1 says <code>held</code> too, Ship of Tools&#39; files for Claude Code are most likely missing: run the installer, as <a href="./updating">Updating</a> describes, and start the session once more.</p><h2 id="Other-things-the-window-says" tabindex="-1">Other things the window says <a class="header-anchor" href="#Other-things-the-window-says" aria-label="Permalink to &quot;Other things the window says {#Other-things-the-window-says}&quot;">​</a></h2><p>A message about a drawing shows on the status line and in the box at the foot of the preview; a message about a selection shows on the status line alone, and a <code>Can&#39;t draw</code> message in the box alone. <a href="/ship-of-tools/stable/guide/previews#Messages-about-the-preview">Messages about the preview</a> says how long the box stays. The message for <code>d</code> over a picture that is not an image file is under <a href="/ship-of-tools/stable/guide/drawing#What-is-not-built">What is not built</a>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">The window says</th><th style="text-align:right;">What it means</th></tr></thead><tbody><tr><td style="text-align:right;"><code>the drawing is full: undo or clear</code></td><td style="text-align:right;">The drawing holds no more ink. Undo or clear to draw more.</td></tr><tr><td style="text-align:right;"><code>Can&#39;t draw here: there is no image file to draw on.</code></td><td style="text-align:right;"><code>d</code> where the preview shows no image file.</td></tr><tr><td style="text-align:right;"><code>Can&#39;t draw while the connection notice covers the preview.</code></td><td style="text-align:right;">The preview is covered by a notice that this window and Ship of Tools on the session&#39;s computer cannot work together, usually because one of them needs updating. The notice says why; nothing can be drawn until it is gone.</td></tr><tr><td style="text-align:right;"><code>selection not shared: this row&#39;s agent takes none</code>, <code>drawing not shared: this row&#39;s agent takes none</code></td><td style="text-align:right;">The session&#39;s agent is not Claude Code.</td></tr><tr><td style="text-align:right;"><code>selection not shared: this host&#39;s daemon does not take selections</code>, <code>drawing not shared: this daemon cannot take a drawing; update it</code></td><td style="text-align:right;">The computer that runs the session has an older Ship of Tools. Update it.</td></tr><tr><td style="text-align:right;"><code>drawing not shared: the image is over 40 megapixels</code></td><td style="text-align:right;">The image is too large to draw on.</td></tr><tr><td style="text-align:right;"><code>drawing not shared: the daemon cannot read this image</code></td><td style="text-align:right;">The service could not read the file as a picture.</td></tr><tr><td style="text-align:right;"><code>selection not shared: &lt;reason&gt;</code>, <code>drawing not shared: &lt;reason&gt;</code></td><td style="text-align:right;">Any other refusal, with the service&#39;s short word for the reason. Select or draw again; if it stays, that word is what to report.</td></tr></tbody></table><h2 id="What-is-not-built" tabindex="-1">What is not built <a class="header-anchor" href="#What-is-not-built" aria-label="Permalink to &quot;What is not built {#What-is-not-built}&quot;">​</a></h2><ul><li><p><strong>Sessions other than Claude Code.</strong> A Codex session&#39;s agent is given neither a selection nor a drawing; the window says so each time, with the <code>takes none</code> message in the table above.</p></li><li><p><strong>Drawing over a PDF page, an SVG or a video&#39;s poster frame.</strong> <code>d</code> works over image files only. Over any other picture it draws nothing, and the box says, for a PDF page: <code>Can&#39;t draw on this PDF page. Drawing (d) marks up an image file (PNG, JPEG, TIFF and the like) for this row&#39;s agent, which sees your marks with your next prompt. To draw anyway, open a PNG of it, or press Shift+d for a blank canvas.</code> To draw on such a picture, save it as a PNG (plotting code can usually save one beside the PDF or SVG) and draw on that, or draw on the canvas.</p></li></ul>',47)])])}const p=t(n,[["render",s]]);export{w as __pageData,p as default};
